def transform(grid):
    """Restore the periodic sequence beneath the diagonal one-cell shift."""
    h, w = len(grid), len(grid[0])
    colors = [v for row in grid for v in row if v != 0]
    period = max(colors)

    # Cells below the diagonal expose sequence positions by their column;
    # cells on/above it expose the sequence one position earlier.
    counts = [Counter() for _ in range(period)]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                sequence_index = c if c < r else c - 1
                counts[sequence_index % period][value] += 1

    sequence = []
    for counter in counts:
        if not counter:
            raise ValueError("insufficient visible cells to infer sequence")
        sequence.append(counter.most_common(1)[0][0])

    return [
        [sequence[(c if c < r else c - 1) % period] for c in range(w)]
        for r in range(h)
    ]
