def transform(grid):
    """Fill masked cells in a periodic grid with a one-step-shifted diagonal."""
    h, w = len(grid), len(grid[0])
    observed = [value for row in grid for value in row if value != 0]
    period = max(observed)

    # Every column has the same periodic background, except for the diagonal;
    # use only off-diagonal observations to recover it.
    base = []
    for c in range(w):
        counts = Counter(
            grid[r][c] for r in range(h)
            if r != c and grid[r][c] != 0
        )
        if not counts:
            # For unusually narrow grids, fall back to all visible cells in col.
            counts = Counter(grid[r][c] for r in range(h) if grid[r][c] != 0)
        if not counts:
            raise ValueError("cannot infer an entirely masked column")
        base.append(counts.most_common(1)[0][0])

    # Enforce the period indicated by the palette (colors are 1..period),
    # using reliable neighboring columns if a column's evidence was sparse.
    for c in range(w):
        expected = base[c % period]
        if c >= period:
            base[c] = expected

    return [
        [base[c - 1 if c == r and c > 0 else (period - 1 if c == r else c) % period]
         for c in range(w)]
        for r in range(h)
    ]
