            votes = Counter(row[c] for row in grid if row[c] != 0)
        cycle.append(votes.most_common(1)[0][0])

    result = []
    for r in range(h):
        row = [cycle[c % period] for c in range(w)]
        if r < w:
            row[r] = cycle[(r - 1) % period]
