    """Restore the repeated row pattern with a one-position shift left of the diagonal."""
    h, w = len(grid), len(grid[0])
    period = max(value for row in grid for value in row)

    # Row 0 shows the full underlying cycle; use its visible entries and infer
    # any masked cycle positions from other rows if necessary.
    cycle = list(grid[0][:period])
    for c, value in enumerate(cycle):
        if value == 0:
            candidates = []
            for r in range(h):
                if grid[r][c] != 0:
                    # For r <= c the cell uses the unshifted cycle position.
                    if r <= c:
                        candidates.append(grid[r][c])
            if not candidates:
                for r in range(h):
                    if grid[r][c] != 0:
                        candidates.append(grid[r][c])
            if not candidates:
                raise ValueError("cannot infer a masked cycle position")
            cycle[c] = candidates[0]

    out = []
    for r in range(h):
        row = []
        for c in range(w):
            idx = (c + 1) % period if c < r else c % period
            row.append(cycle[idx])
        out.append(row)
    return out
